import re, os, glob

folder = "30_Library/100_zettelkasten"

def esc(v):
    return v.replace("\\", "\\\\").replace('"', '\\"')

def fix_wrapped_key(lines, end, key):
    i = 1
    while i < end:
        m = re.match(rf'^{re.escape(key)}:(.*)$', lines[i].rstrip("\n"))
        if m and m.group(1).strip():
            j = i + 1
            cont = []
            while j < end and (lines[j].startswith(" ") or lines[j].startswith("\t")) and not re.match(r'^\s+[A-Za-z0-9_.-]+:\s', lines[j]) and not lines[j].strip().startswith("-"):
                cont.append(lines[j].rstrip("\n").strip())
                j += 1
            if cont:
                first = m.group(1).strip()
                value = (first + " " + " ".join(cont)).strip()
                if len(value) >= 2 and value[0] == value[-1] == "'":
                    value = value[1:-1].replace("''", "'")
                new_line = f'{key}: "{esc(value)}"\n'
                lines[i:j] = [new_line]
                return True, value
        i += 1
    return False, None

# every remaining zettelkasten file, scan generically for wrapped `proposition:` or `definition:`
fixed = []
for path in glob.glob(folder + "/*.md"):
    with open(path, encoding="utf-8") as f:
        lines = f.readlines()
    if not lines or not lines[0].startswith("---"):
        continue
    try:
        end = next(i for i in range(1, len(lines)) if lines[i].rstrip("\n") == "---")
    except StopIteration:
        continue
    changed = False
    for key in ("proposition", "definition"):
        ok, value = fix_wrapped_key(lines, end, key)
        if ok:
            changed = True
            fixed.append((path, key, value))
            end = next(i for i in range(1, len(lines)) if lines[i].rstrip("\n") == "---")
    if changed:
        with open(path, "w", encoding="utf-8") as f:
            f.writelines(lines)

print("Fixed", len(fixed), "fields")
for p, k, v in fixed:
    print(f" - {p} [{k}] -> {v[:90]}...")
